import 'svelte/internal/disclose-version';
import * as $ from 'svelte/internal/client';
import { box } from "svelte-toolbelt";
import { noop } from "../../../internal/noop.js";
import { useDialogRoot } from "../../dialog/dialog.svelte.js";

export default function Alert_dialog($$anchor, $$props) {
	$.push($$props, true);

	let open = $.prop($$props, 'open', 15, false),
		onOpenChange = $.prop($$props, 'onOpenChange', 3, noop);

	useDialogRoot({
		variant: box.with(() => "alert-dialog"),
		open: box.with(() => open(), (v) => {
			open(v);
			onOpenChange()(v);
		})
	});

	var fragment = $.comment();
	var node = $.first_child(fragment);

	$.snippet(node, () => $$props.children ?? $.noop);
	$.append($$anchor, fragment);
	$.pop();
}
